-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.same_flight(p_from text, p_to text, p_on date)
 RETURNS TABLE(creator_id uuid, name text, photo_url text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p.id, p.name, p.photo_url
  from public.flights f
  join public.profiles p on p.id = f.creator_id
  where f.share_with_community
    and f.flown_on = p_on
    and upper(f.from_iata) = upper(p_from)
    and upper(f.to_iata)   = upper(p_to)
    and f.creator_id <> auth.uid()
    and p.status = 'active'
    and coalesce(p.is_test, false) = false
    and p.deletion_requested_at is null
    -- You only see other people if you are sharing too.
    and exists (
      select 1 from public.flights mine
      where mine.creator_id = auth.uid()
        and mine.share_with_community
        and mine.flown_on = p_on
        and upper(mine.from_iata) = upper(p_from)
        and upper(mine.to_iata)   = upper(p_to)
    )
  group by p.id, p.name, p.photo_url
$function$;
